from __future__ import annotations


def generate_openmodelica_flyback_script(
    vin_v: float = 24.0,
    vout_target_v: float = 1000.0,
    f_sw_hz: float = 100000.0,
    r_load_ohm: float = 20000.0,
    stop_time_s: float = 0.002,
    output_mat_path: str = "flyback_res.mat",
) -> str:
    """Generates an OpenModelica (.mos) script to simulate a power converter transient."""
    return f"""// OpenModelica Headless Simulation Script
// Generated by Mendex Engineering Studio v1.5
loadModel(Modelica);
getErrorString();

model FlybackConverter
  parameter Real Vin = {vin_v};
  parameter Real Vout_target = {vout_target_v};
  parameter Real Fsw = {f_sw_hz};
  parameter Real Rload = {r_load_ohm};
  Real v_out(start=0.0);
  Real i_pri(start=0.0);
equation
  der(v_out) = (Vin * 40.0 - v_out) / (Rload * 10e-6);
  der(i_pri) = (Vin - 0.1 * i_pri) / 150e-6;
end FlybackConverter;
getErrorString();

simulate(FlybackConverter, stopTime={stop_time_s}, numberOfIntervals=1000, outputFormat="mat");
getErrorString();
"""
